<script setup lang="ts">
import { computed, ref } from 'vue'

type Courier = {
  name: string
  code: string
  description: string
  services: string[]
  enabled: boolean
  pickup: boolean
  dropoff: boolean
}

const emit = defineEmits<{ back: [] }>()

const activeSection = ref('Informasi Toko')
const storeName = ref('Koperasi Tenun & Batik Nusantara')
const tagline = ref('Kain Tenun Ikat & Batik Mahakarya Perajin Nusantara')
const description = ref('Koperasi produsen kain tenun ikat dan batik tulis tradisional yang memberdayakan perajin lokal Nusantara. Kami menjaga mutu karya tenun dan batik otentik dengan pewarna alami.')
const category = ref('Wastra & Tenun')
const contactName = ref('Maria Yosefina')
const contactEmail = ref('halo@wastranusantara.id')
const contactPhone = ref('0812-3456-7890')
const whatsappNumber = ref('6281234567890')
const address = ref('Jl. Ahmad Yani No. 18, Kelurahan Ngedukelu')
const village = ref('Ngedukelu')
const district = ref('Bajawa')
const regency = ref('Kabupaten Ngada')
const province = ref('Nusa Tenggara Timur')
const postalCode = ref('86411')
const latitude = ref('-8.7908')
const longitude = ref('120.9748')
const storeSince = '2022'
const saveMessage = ref('')
const formError = ref('')
const isPublic = ref(true)
const fulfillmentMethods = ref(['Pick-up Kurir', 'Drop-off Gerai'])
const schedule = ref([
  { day: 'Senin', enabled: true, open: '08:00', close: '17:00' },
  { day: 'Selasa', enabled: true, open: '08:00', close: '17:00' },
  { day: 'Rabu', enabled: true, open: '08:00', close: '17:00' },
  { day: 'Kamis', enabled: true, open: '08:00', close: '17:00' },
  { day: 'Jumat', enabled: true, open: '08:00', close: '16:30' },
  { day: 'Sabtu', enabled: true, open: '08:00', close: '13:00' },
  { day: 'Minggu', enabled: false, open: '08:00', close: '13:00' },
])
const couriers = ref<Courier[]>([
  { name: 'J&T Express', code: 'J&T', description: 'Jangkauan nasional · Pick-up harian', services: ['EZ', 'Eco'], enabled: true, pickup: true, dropoff: true },
  { name: 'SiCepat Ekspres', code: 'SC', description: 'Reguler dan kargo antarpulau', services: ['REG', 'GOKIL'], enabled: true, pickup: true, dropoff: true },
  { name: 'JNE', code: 'JNE', description: 'Layanan OKE, REG, dan YES', services: ['OKE', 'REG', 'YES'], enabled: true, pickup: false, dropoff: true },
  { name: 'Pos Indonesia', code: 'POS', description: 'Menjangkau wilayah 3T dan desa', services: ['Pos Reguler', 'Pos Kargo'], enabled: false, pickup: false, dropoff: true },
])
const profileCompletion = computed(() => {
  const requiredFields = [storeName.value, description.value, contactPhone.value, address.value, postalCode.value]
  const completed = requiredFields.filter((value) => value.trim()).length
  return Math.round((completed / requiredFields.length) * 100)
})
const locationSummary = computed(() => `${regency.value}, ${province.value}`)

function toggleMethod(method: string) {
  fulfillmentMethods.value = fulfillmentMethods.value.includes(method)
    ? fulfillmentMethods.value.filter((activeMethod) => activeMethod !== method)
    : [...fulfillmentMethods.value, method]
}

function saveProfile() {
  if (!storeName.value.trim() || !contactPhone.value.trim() || !address.value.trim()) {
    formError.value = 'Nama toko, nomor telepon, dan alamat wajib diisi.'
    activeSection.value = 'Informasi Toko'
    return
  }
  if (!couriers.value.some((courier) => courier.enabled)) {
    formError.value = 'Aktifkan minimal satu kurir untuk menerima pesanan.'
    activeSection.value = 'Pengiriman & Kurir'
    return
  }
  formError.value = ''
  saveMessage.value = 'Perubahan profil toko berhasil disimpan.'
  window.setTimeout(() => { saveMessage.value = '' }, 2800)
}

function toggleSection(section: string) {
  activeSection.value = section
  document.getElementById(`profile-${section === 'Informasi Toko' ? 'identity' : section === 'Lokasi & Operasional' ? 'location' : 'couriers'}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' })
}
</script>

<template>
  <main class="seller-store-profile">
    <header class="store-profile-heading">
      <div><nav class="store-profile-breadcrumb"><button type="button" @click="emit('back')">Portal Mitra UMKM</button><span>›</span><b>Profil Toko &amp; Kurir</b></nav><span class="profile-live"><i></i> TOKO TERVERIFIKASI</span><h1>Profil Toko &amp; Pengiriman</h1><p>Kelola informasi publik toko, lokasi operasional, jam layanan, dan mitra logistik yang digunakan.</p></div>
      <div class="profile-heading-actions"><button type="button" class="profile-preview-action" @click="isPublic = !isPublic">{{ isPublic ? '◉' : '○' }} &nbsp; {{ isPublic ? 'Toko Tayang' : 'Toko Disembunyikan' }}</button><button type="button" class="profile-save-action" @click="saveProfile">▣ &nbsp; Simpan Perubahan</button></div>
    </header>

    <section class="profile-status-strip"><div class="profile-status-mark">✓</div><div><b>Profil mitra terverifikasi</b><small>Dokumen legalitas dan rekening utama telah dikonfirmasi.</small></div><span class="profile-status-divider"></span><div><small>MENJADI MITRA SEJAK</small><b>{{ storeSince }}</b></div><span class="profile-status-divider"></span><div><small>RATING TOKO</small><b class="profile-rating">★ 4.9 <small>(64 ulasan)</small></b></div></section>

    <nav class="profile-section-tabs" aria-label="Bagian profil toko"><button v-for="section in ['Informasi Toko', 'Lokasi & Operasional', 'Pengiriman & Kurir']" :key="section" type="button" :class="{ active: activeSection === section }" @click="toggleSection(section)">{{ section }}</button><span><i></i> Perubahan tersimpan otomatis</span></nav>

    <div class="store-profile-layout">
      <div class="profile-form-column">
        <section id="profile-identity" class="profile-panel identity-panel"><header class="profile-panel-heading"><span class="profile-panel-icon">▤</span><div><h2>Identitas &amp; Informasi Publik</h2><p>Informasi ini tampil pada halaman toko yang dilihat pembeli.</p></div><span class="required-note">* Wajib diisi</span></header>
          <div class="store-brand-editor"><div class="store-avatar">KB<span>✓</span></div><div><b>Logo Toko</b><small>Gunakan logo yang jelas dan mudah dikenali pembeli.</small><button type="button" @click="saveMessage = 'Unggah logo toko melalui pengelola aset.'">Ganti Logo</button></div><span class="brand-image-size">PNG / JPG<br />Maks. 2 MB</span></div>
          <label class="profile-field">Nama Toko <b>*</b><input v-model="storeName" maxlength="60" placeholder="Nama toko yang tampil ke pembeli" /><small>{{ storeName.length }} / 60 karakter</small></label>
          <label class="profile-field">Tagline Toko <input v-model="tagline" maxlength="100" placeholder="Satu kalimat singkat tentang tokomu" /><small>{{ tagline.length }} / 100 karakter</small></label>
          <label class="profile-field">Kategori Utama <b>*</b><select v-model="category"><option>Kopi &amp; Minuman Herbal</option><option>Makanan &amp; Camilan</option><option>Wastra &amp; Tenun</option><option>Kriya Rumah</option><option>Herbal &amp; Perawatan</option></select></label>
          <label class="profile-field">Cerita Singkat Toko <b>*</b><textarea v-model="description" rows="4" maxlength="600" placeholder="Ceritakan produk, proses, dan komunitas yang kamu berdayakan."></textarea><small>{{ description.length }} / 600 karakter</small></label>
          <div class="profile-field-grid"><label class="profile-field">Nama Narahubung <b>*</b><input v-model="contactName" autocomplete="name" /></label><label class="profile-field">Email Toko <b>*</b><input v-model="contactEmail" type="email" autocomplete="email" /></label></div>
          <div class="profile-field-grid"><label class="profile-field">Nomor Telepon Toko <b>*</b><input v-model="contactPhone" type="tel" autocomplete="tel" /><small>Digunakan untuk informasi pesanan.</small></label><label class="profile-field">Nomor WhatsApp <input v-model="whatsappNumber" type="tel" /><small>Gunakan kode negara, contoh 62812...</small></label></div>
        </section>

        <section id="profile-location" class="profile-panel location-panel"><header class="profile-panel-heading"><span class="profile-panel-icon location-icon">⌖</span><div><h2>Lokasi &amp; Jam Operasional</h2><p>Lokasi digunakan untuk estimasi ongkir dan layanan pick-up kurir.</p></div></header>
          <label class="profile-field">Alamat Lengkap <b>*</b><textarea v-model="address" rows="2" autocomplete="street-address"></textarea></label>
          <div class="profile-field-grid"><label class="profile-field">Desa / Kelurahan <input v-model="village" /></label><label class="profile-field">Kecamatan <input v-model="district" /></label></div>
          <div class="profile-field-grid"><label class="profile-field">Kabupaten / Kota <input v-model="regency" /></label><label class="profile-field">Provinsi <select v-model="province"><option>Nusa Tenggara Timur</option><option>Jawa Timur</option><option>Jawa Barat</option><option>Daerah Istimewa Yogyakarta</option><option>Bali</option></select></label></div>
          <div class="profile-field-grid"><label class="profile-field">Kode Pos <b>*</b><input v-model="postalCode" inputmode="numeric" autocomplete="postal-code" /></label><div class="coordinate-field"><span>KOORDINAT LOKASI</span><div><label>Lat <input v-model="latitude" aria-label="Garis lintang" /></label><label>Long <input v-model="longitude" aria-label="Garis bujur" /></label></div></div></div>
          <div class="location-map-preview"><div class="map-grid"><span class="map-road profile-road-a"></span><span class="map-road profile-road-b"></span><span class="map-road profile-road-c"></span><i>●</i></div><div><b>Sentra Tenun &amp; Batik</b><small>{{ locationSummary }} · 86411</small></div><button type="button" @click="saveMessage = 'Peta lokasi toko diperbarui.'">⌖ &nbsp; Atur Lokasi Peta</button></div>
          <div class="operation-hours"><header><div><b>Jam Operasional Toko</b><small>Pembeli dapat melihat jadwal layanan toko.</small></div><label class="profile-toggle"><input v-model="isPublic" type="checkbox" /><span></span><b>{{ isPublic ? 'Toko Buka' : 'Toko Tutup' }}</b></label></header><div v-for="day in schedule" :key="day.day" class="operation-day"><label><input v-model="day.enabled" type="checkbox" />{{ day.day }}</label><template v-if="day.enabled"><input v-model="day.open" type="time" :aria-label="`Jam buka ${day.day}`" /><span>s.d.</span><input v-model="day.close" type="time" :aria-label="`Jam tutup ${day.day}`" /></template><small v-else>Libur</small></div></div>
        </section>

        <section id="profile-couriers" class="profile-panel courier-config-panel"><header class="profile-panel-heading"><span class="profile-panel-icon courier-icon">▣</span><div><h2>Metode Fulfillment &amp; Mitra Kurir</h2><p>Aktifkan opsi pengiriman yang tersedia dari lokasi tokomu.</p></div></header>
          <div class="fulfillment-options"><button v-for="method in ['Pick-up Kurir', 'Drop-off Gerai', 'Kargo Antarpulau']" :key="method" type="button" :class="{ selected: fulfillmentMethods.includes(method) }" :aria-pressed="fulfillmentMethods.includes(method)" @click="toggleMethod(method)"><i>{{ fulfillmentMethods.includes(method) ? '✓' : '' }}</i><span><b>{{ method }}</b><small>{{ method === 'Pick-up Kurir' ? 'Kurir menjemput paket ke toko' : method === 'Drop-off Gerai' ? 'Antar paket ke gerai terdekat' : 'Untuk pesanan berukuran besar' }}</small></span></button></div>
          <div class="courier-list-heading"><b>Mitra Kurir Tersedia</b><small>{{ couriers.filter((courier) => courier.enabled).length }} kurir aktif</small></div>
          <article v-for="courier in couriers" :key="courier.code" class="profile-courier-card" :class="{ disabled: !courier.enabled }"><span class="courier-logo">{{ courier.code }}</span><div class="profile-courier-main"><b>{{ courier.name }}</b><small>{{ courier.description }}</small><div class="courier-service-tags"><span v-for="service in courier.services" :key="service">{{ service }}</span></div><div class="courier-mode-options"><label><input v-model="courier.pickup" type="checkbox" :disabled="!courier.enabled" /> Pick-up</label><label><input v-model="courier.dropoff" type="checkbox" :disabled="!courier.enabled" /> Drop-off</label></div></div><label class="profile-toggle courier-toggle"><input v-model="courier.enabled" type="checkbox" :aria-label="`Aktifkan ${courier.name}`" /><span></span><b>{{ courier.enabled ? 'Aktif' : 'Nonaktif' }}</b></label></article>
          <button type="button" class="courier-help-link" @click="saveMessage = 'Permintaan penambahan mitra kurir telah dicatat.'">＋ Ajukan penambahan mitra kurir</button>
        </section>
        <p v-if="formError" class="profile-form-error" role="alert">{{ formError }}</p>
      </div>

      <aside class="profile-aside"><section class="public-store-card"><header><div><small>PRATINJAU TOKO PUBLIK</small><b>{{ isPublic ? 'Tayang di marketplace' : 'Toko disembunyikan' }}</b></div><i :class="{ off: !isPublic }"></i></header><div class="public-cover"><img src="https://images.unsplash.com/photo-1605000797499-95a51c5269ae?w=700&q=82" alt="Sentra tenun untuk sampul toko" /></div><div class="public-store-identity"><span class="public-avatar">KB</span><div><b>{{ storeName }}</b><small>✓ Mitra Terverifikasi · {{ locationSummary }}</small></div></div><p>{{ tagline }}</p><div class="public-store-stats"><span>★ <b>4.9</b> (64)</span><span>◇ <b>98%</b> respon</span><span>▤ Sejak {{ storeSince }}</span></div><button type="button" :disabled="!isPublic" @click="saveMessage = 'Pratinjau halaman publik dibuka.'">Lihat Halaman Toko ↗</button></section>
        <section class="profile-completion-card"><header><div><b>Kelengkapan Profil</b><strong>{{ profileCompletion }}%</strong></div><div class="completion-progress"><i :style="{ width: `${profileCompletion}%` }"></i></div></header><ul><li v-for="item in [{ label: 'Informasi dan kontak toko', done: Boolean(storeName && contactPhone) }, { label: 'Alamat lokasi operasional', done: Boolean(address && postalCode) }, { label: 'Mitra kurir aktif', done: couriers.some((courier) => courier.enabled) }, { label: 'Jam operasional diatur', done: schedule.some((day) => day.enabled) }]" :key="item.label" :class="{ done: item.done }"><i>{{ item.done ? '✓' : '○' }}</i>{{ item.label }}</li></ul></section>
        <section class="profile-support-card"><span>✧</span><div><b>Butuh Bantuan Mitra?</b><p>Pendamping PasarPintar siap membantu pembaruan profil dan aktivasi kurir wilayah Bajawa.</p><button type="button" @click="saveMessage = 'Tim pendamping akan menghubungi kontak tokomu.'">Hubungi Pendamping →</button></div></section></aside>
    </div>

    <footer class="profile-sticky-actions"><span><i></i> Semua perubahan disimpan untuk pratinjau</span><button type="button" @click="emit('back')">Batal</button><button type="button" class="profile-save-action" @click="saveProfile">▣ &nbsp; Simpan Perubahan</button></footer>
    <div v-if="formError" class="profile-toast error" role="alert">{{ formError }}</div><div v-else-if="saveMessage" class="profile-toast" role="status">✓ &nbsp; {{ saveMessage }}</div>
  </main>
</template>

